import{_ as a,o as n,c as t,aN as m}from"./chunks/framework.D31DlcCL.js";const l="/img/tree-both-ends.svg",r="/img/tree-one-end.svg",o="/img/tree-no-ends.svg",e="/img/tree-circular.svg",b=JSON.parse('{"title":"小学数学趣题巧解：植树问题的“指缝”奥秘","description":"植树问题是小学数学中极具逻辑挑战的趣题。如何区分“两端都种”还是“一端不种”？本文通过形象的“指缝”比喻和精美的图解，带你彻底攻克植树问题的所有变式。","frontmatter":{"title":"小学数学趣题巧解：植树问题的“指缝”奥秘","date":"2026-02-08T16:00:00.000Z","categories":["数学"],"tags":["小学数学","趣题巧解","植树问题","奥数入门"],"description":"植树问题是小学数学中极具逻辑挑战的趣题。如何区分“两端都种”还是“一端不种”？本文通过形象的“指缝”比喻和精美的图解，带你彻底攻克植树问题的所有变式。","cover":"/img/tree-both-ends.svg","top_img":"/img/banner.svg","toc_number":true},"headers":[],"relativePath":"posts/primary-math-clever-solutions-tree-planting.md","filePath":"posts/primary-math-clever-solutions-tree-planting.md","lastUpdated":null}'),p={name:"posts/primary-math-clever-solutions-tree-planting.md"};function i(c,s,h,g,d,u){return n(),t("div",null,[...s[0]||(s[0]=[m('<h1 id="小学数学趣题巧解-植树问题的-指缝-奥秘" tabindex="-1">小学数学趣题巧解：植树问题的“指缝”奥秘 <a class="header-anchor" href="#小学数学趣题巧解-植树问题的-指缝-奥秘" aria-label="Permalink to &quot;小学数学趣题巧解：植树问题的“指缝”奥秘&quot;">​</a></h1><p>在小学数学的竞赛和考试中，<strong>“植树问题”</strong>（Tree Planting Problem）是一个出镜率极高、却又极其容易掉坑的题型。</p><p>很多同学一看到“每隔 5 米种一棵”，就急着去用总长度除以 5，结果往往不是多了一棵就是少了一棵。其实，植树问题的核心不在于“树”，而在于**“间隔”**。</p><p>今天，我们就用最通俗的方式，拆解植树问题的四大模型。</p><hr><h2 id="核心法宝-看你的手" tabindex="-1">核心法宝：看你的手！ <a class="header-anchor" href="#核心法宝-看你的手" aria-label="Permalink to &quot;核心法宝：看你的手！&quot;">​</a></h2><p>在学习植树问题之前，请伸出你的右手，张开五指。</p><ul><li><strong>手指</strong>：代表“树”。</li><li><strong>指缝</strong>：代表“间隔”。</li></ul><p>数一数：<strong>5 根手指，中间有几个指缝？</strong> 答案是：<strong>4 个</strong>。</p><p>这就是植树问题的基本逻辑：<strong>树的棵数 = 间隔数 + 1</strong>（在两端都种的情况下）。</p><hr><h2 id="模型一-直线植树-两端都种" tabindex="-1">模型一：直线植树（两端都种） <a class="header-anchor" href="#模型一-直线植树-两端都种" aria-label="Permalink to &quot;模型一：直线植树（两端都种）&quot;">​</a></h2><p>这是最常见的情况。比如在马路的两边种树，起点和终点都要种。</p><p><img src="'+l+'" alt="两端都种图解"></p><ul><li><strong>特点</strong>：头尾都有树。</li><li><strong>公式</strong>： <ul><li>间隔数 = 总长 ÷ 间距</li><li><strong>棵数 = 间隔数 + 1</strong></li><li>总长 = 间隔数 × 间距</li></ul></li></ul><p><strong>【例题 1】</strong> 在一条长 100 米的小路一侧植树，每隔 5 米种一棵（两端都种）。一共需要多少棵树苗？ <strong>解析</strong>：</p><ol><li>先求间隔数：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>0</mn><mn>0</mn><mo>÷</mo><mn>5</mn><mo>=</mo><mn>2</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">100 \\div 5 = 20</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mbin">÷</span><span class="mord mathrm">5</span><span class="mrel">=</span><span class="mord mathrm">2</span><span class="mord mathrm">0</span></span></span></span>（个）。</li><li>因为两端都种，所以棵数比间隔多 1：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>2</mn><mn>0</mn><mo>+</mo><mn>1</mn><mo>=</mo><mn>2</mn><mn>1</mn></mrow><annotation encoding="application/x-tex">20 + 1 = 21</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">2</span><span class="mord mathrm">0</span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mrel">=</span><span class="mord mathrm">2</span><span class="mord mathrm">1</span></span></span></span>（棵）。 <strong>答案</strong>：21 棵。</li></ol><hr><h2 id="模型二-直线植树-只种一端" tabindex="-1">模型二：直线植树（只种一端） <a class="header-anchor" href="#模型二-直线植树-只种一端" aria-label="Permalink to &quot;模型二：直线植树（只种一端）&quot;">​</a></h2><p>这种情况常见于：一端是路口，另一端是建筑物；或者“锯木头”、“爬楼梯”等变式。</p><p><img src="'+r+'" alt="只种一端图解"></p><ul><li><strong>特点</strong>：一头有树，一头没树。</li><li><strong>公式</strong>： <ul><li><strong>棵数 = 间隔数</strong></li><li>间隔数 = 总长 ÷ 间距</li></ul></li></ul><p><strong>【例题 2】</strong> 锯一根木头，每锯一段要 3 分钟。要把木头锯成 5 段，一共要多少分钟？ <strong>解析</strong>：</p><ol><li>“段数”相当于“树”，而“锯的次数”相当于“间隔”。</li><li>把木头锯成 5 段，只需要锯 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>5</mn><mo>−</mo><mn>1</mn><mo>=</mo><mn>4</mn></mrow><annotation encoding="application/x-tex">5 - 1 = 4</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">5</span><span class="mbin">−</span><span class="mord mathrm">1</span><span class="mrel">=</span><span class="mord mathrm">4</span></span></span></span> 次（只种一端模型）。</li><li>总时间：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>4</mn><mo>×</mo><mn>3</mn><mo>=</mo><mn>1</mn><mn>2</mn></mrow><annotation encoding="application/x-tex">4 \\times 3 = 12</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">4</span><span class="mbin">×</span><span class="mord mathrm">3</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">2</span></span></span></span>（分钟）。 <strong>答案</strong>：12 分钟。</li></ol><hr><h2 id="模型三-直线植树-两端都不种" tabindex="-1">模型三：直线植树（两端都不种） <a class="header-anchor" href="#模型三-直线植树-两端都不种" aria-label="Permalink to &quot;模型三：直线植树（两端都不种）&quot;">​</a></h2><p>常见于：在两座教学楼之间摆花，或者在两根电线杆之间挂灯笼。</p><p><img src="'+o+'" alt="两端都不种图解"></p><ul><li><strong>特点</strong>：头尾都不能种。</li><li><strong>公式</strong>： <ul><li><strong>棵数 = 间隔数 - 1</strong></li><li>间隔数 = 总长 ÷ 间距</li></ul></li></ul><p><strong>【例题 3】</strong> 两座楼房之间相距 30 米，每隔 3 米栽一棵雪松（两端都不栽）。一共栽了多少棵？ <strong>解析</strong>：</p><ol><li>间隔数：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>3</mn><mn>0</mn><mo>÷</mo><mn>3</mn><mo>=</mo><mn>1</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">30 \\div 3 = 10</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">3</span><span class="mord mathrm">0</span><span class="mbin">÷</span><span class="mord mathrm">3</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span></span></span></span>（个）。</li><li>两端都不栽：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>0</mn><mo>−</mo><mn>1</mn><mo>=</mo><mn>9</mn></mrow><annotation encoding="application/x-tex">10 - 1 = 9</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mbin">−</span><span class="mord mathrm">1</span><span class="mrel">=</span><span class="mord mathrm">9</span></span></span></span>（棵）。 <strong>答案</strong>：9 棵。</li></ol><hr><h2 id="模型四-封闭图形植树" tabindex="-1">模型四：封闭图形植树 <a class="header-anchor" href="#模型四-封闭图形植树" aria-label="Permalink to &quot;模型四：封闭图形植树&quot;">​</a></h2><p>常见于：在圆形花坛四周、长方形操场四周种树。</p><p><img src="'+e+'" alt="封闭图形图解"></p><ul><li><strong>特点</strong>：起点就是终点，首尾相接。</li><li><strong>公式</strong>： <ul><li><strong>棵数 = 间隔数</strong></li><li>间隔数 = 周长 ÷ 间距</li></ul></li></ul><p><strong>【例题 4】</strong> 一个圆形池塘周长是 120 米，每隔 6 米种一棵柳树。一共要种多少棵？ <strong>解析</strong>：</p><ol><li>封闭图形中，间隔数和棵数相等。</li><li><span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>2</mn><mn>0</mn><mo>÷</mo><mn>6</mn><mo>=</mo><mn>2</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">120 \\div 6 = 20</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">2</span><span class="mord mathrm">0</span><span class="mbin">÷</span><span class="mord mathrm">6</span><span class="mrel">=</span><span class="mord mathrm">2</span><span class="mord mathrm">0</span></span></span></span>（棵）。 <strong>答案</strong>：20 棵。</li></ol><hr><h2 id="避坑指南-校验三部曲" tabindex="-1">避坑指南：校验三部曲 <a class="header-anchor" href="#避坑指南-校验三部曲" aria-label="Permalink to &quot;避坑指南：校验三部曲&quot;">​</a></h2><ol><li><strong>审题</strong>：看清是“一侧”还是“两侧”。如果是“两侧”，最后结果要 <strong>乘以 2</strong>。</li><li><strong>定型</strong>：判断属于哪种模型（两端种、不种还是封闭图形）。</li><li><strong>验算</strong>：小数据模拟。比如 10 米长，每隔 5 米种一棵，如果是两端都种，手画一下：0m, 5m, 10m 共 3 棵。公式 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>0</mn><mo>÷</mo><mn>5</mn><mo>+</mo><mn>1</mn><mo>=</mo><mn>3</mn></mrow><annotation encoding="application/x-tex">10 \\div 5 + 1 = 3</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mbin">÷</span><span class="mord mathrm">5</span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mrel">=</span><span class="mord mathrm">3</span></span></span></span>，正确！</li></ol><hr><h2 id="闯关练习" tabindex="-1">闯关练习 <a class="header-anchor" href="#闯关练习" aria-label="Permalink to &quot;闯关练习&quot;">​</a></h2><ol><li><strong>(基础关)</strong> 一条走廊长 24 米，每隔 3 米放一盆花（两端都放）。一共要放多少盆花？</li><li><strong>(进阶关)</strong> 小明家住在 5 楼，他从 1 楼爬到 2 楼用了 10 秒。照这样计算，他从 1 楼爬到 5 楼需要多少秒？</li><li><strong>(挑战关)</strong> 在一个正方形操场四周种树，每边种 5 棵（四个角都种）。一共种了多少棵？</li></ol><hr><p><em>提示：解题时一定要先画出草图，确定属于哪种模型哦！</em></p>',46)])])}const k=a(p,[["render",i]]);export{b as __pageData,k as default};
